export async function uploadData(file) {
  // Fake a delay
  await new Promise((r) => setTimeout(r, 500));

  return {
    success: true,
    data: Array.from({ length: 20 }, () => Math.floor(Math.random() * 100))
  };
}
export async function analyzeData(data, type) {
  // Simulate delay
  await new Promise((r) => setTimeout(r, 500));

  const fakePredictions = data.map((val, i) => val + Math.random() * 5 - 2.5);

  // Sample small red/blue line plot in base64 (1x1 pixel image, safe for testing)
  const dummyBase64 =
    "data:image/png;base64,";

  return {
    success: true,
    results: {
      coefficients: [0.42],
      intercept: 5.1,
      predictions: fakePredictions,
      r2_score: 0.91,
      mse: 7.22,
      report: `Fake analysis done for type: ${type}`
    },
    plot_base64: `data:image/png;base64,${dummyBase64}`
  };
}
 
